-- DDL: structure changes (usually auto-committed)
CREATE TABLE employees (emp_id INT PRIMARY KEY, name VARCHAR(100));
ALTER TABLE employees ADD COLUMN salary DECIMAL(10,2);
TRUNCATE TABLE employees;
DROP TABLE employees;

-- DML: data changes (transactional)
INSERT INTO employees (emp_id, name, salary) VALUES (1, 'Alice', 50000);
UPDATE employees SET salary = 55000 WHERE emp_id = 1;
DELETE FROM employees WHERE emp_id = 1;
SELECT * FROM employees;

-- Scalar subquery: above-average earners
SELECT employee_name, salary
FROM employees
WHERE salary > (SELECT AVG(salary) FROM employees);

-- IN subquery: employees in specific departments
SELECT employee_name
FROM employees
WHERE department_id IN (
  SELECT department_id FROM departments WHERE location = 'London'
);

-- Correlated subquery: highest earner per department
SELECT employee_name, salary
FROM employees e
WHERE salary = (
  SELECT MAX(salary) FROM employees x WHERE x.department_id = e.department_id
);

-- EXISTS subquery: employees with at least one order
SELECT employee_name
FROM employees e
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.employee_id = e.employee_id);

-- One primary key (composite allowed); multiple unique keys allowed
CREATE TABLE customers (
  customer_id INT PRIMARY KEY,          -- the single PK
  email VARCHAR(150) UNIQUE,            -- unique key #1
  phone VARCHAR(20) UNIQUE              -- unique key #2
);

-- Foreign key referencing the parent primary key
CREATE TABLE orders (
  order_id INT PRIMARY KEY,
  customer_id INT,
  amount DECIMAL(10,2),
  CONSTRAINT fk_customer FOREIGN KEY (customer_id)
    REFERENCES customers(customer_id)
);

