@BeforeAll
static void seed() throws SQLException {
    con = DriverManager.getConnection(URL, USER, PASS);
    try (PreparedStatement ps = con.prepareStatement(
            "INSERT INTO customers (customer_id, email) VALUES (?, ?)")) {
        testCustomerId = 900000 + (int)(System.currentTimeMillis() % 1000);
        ps.setInt(1, testCustomerId);
        ps.setString(2, "qa_" + System.currentTimeMillis() + "@test.com");
        ps.executeUpdate();
    }
}

@AfterAll
static void cleanUp() throws SQLException {
    // delete children first to respect foreign keys
    try (Statement st = con.createStatement()) {
        st.executeUpdate("DELETE FROM orders WHERE customer_id = " + testCustomerId);
        st.executeUpdate("DELETE FROM customers WHERE customer_id = " + testCustomerId);
    } finally {
        con.close();
    }
}

